mapper.select:
SELECT GUARANTEE_ID, GUARANTEE_TYPE, GUARANTEE_AMOUNT, GUARANTEE_DATE,
       GUARANTEE_STATUS, GUARANTEE_TARGET, GUARANTEED_PARTY_ID,
       COMPANY_ID, CREATE_TIME
FROM TBL_GUARANTEE
WHERE 1=1

    AND GUARANTEE_ID LIKE CONCAT('%', #{guaranteeNumber}, '%')


    AND GUARANTEE_TYPE = #{guaranteeType}


    AND GUARANTEE_STATUS = #{guaranteeStatus}


    AND GUARANTEED_PARTY_ID LIKE CONCAT('%', #{applicant}, '%')


    AND GUARANTEE_TARGET LIKE CONCAT('%', #{beneficiary}, '%')


    AND CREATE_TIME >= #{startDate}


    AND CREATE_TIME <= #{endDate}

ORDER BY CREATE_TIME DESC

